1951	export function patternRule(declaration, { selfExclude = null } = {}) {
1952	  const where = `the declared check "${declaration.id}"`;
1953	  if (typeof declaration.id !== 'string' || !declaration.id.trim()) {
1954	    throw new Error('a declared check needs a non-empty "id"');
1955	  }
1956	  if (declaration.severity !== 'blocking' && declaration.severity !== 'advisory') {
1957	    throw new Error(`${where}: severity must be "blocking" or "advisory", not ${JSON.stringify(declaration.severity)}`);
1958	  }
1959	  // `since` is the date the check was authored, and the engine holds a blocking
1960	  // check to advisory for its first GRACE_DAYS from it (findings.mjs). Validated
1961	  // here rather than shrugged off downstream: a misspelled date silently grants no
1962	  // grace, which lands as a red build on the run that thought it had one.
1963	  if (declaration.since !== undefined && !/^\d{4}-\d{2}-\d{2}$/.test(declaration.since)) {
1964	    throw new Error(`${where}: "since" is the date this check was added, as YYYY-MM-DD, not ${JSON.stringify(declaration.since)}`);
1965	  }
1966	  const spec = compileSpec(partitionSpecKeys(declaration, 'spec', []), null, where);
1967	  validateEntryShapes(spec, where);
1968	  const classPatterns = (names) => (names ?? []).map((n) => {
1969	    if (!FILE_CLASSES[n]) {
1970	      throw new Error(`${where}: "${n}" is not a file class — the classes are: ${Object.keys(FILE_CLASSES).join(', ')}`);
1971	    }
1972	    return FILE_CLASSES[n];
1973	  });
1974	  const scanClasses = classPatterns(spec.scanFileClasses);
1975	  if (scanClasses.length && typeof spec.scanFiles === 'string') {
1976	    throw new Error(`${where}: scanFileClasses cannot combine with an exact-path scanFiles`);
1977	  }
1978	  // The field-named scan form: its own key, so nothing downstream has to ask
1979	  // which of scanFiles' three shapes it is holding.
1980	  if (spec.scanFiles !== null && typeof spec.scanFiles === 'object' && !(spec.scanFiles instanceof RegExp)) {
1981	    spec.namedScan = spec.scanFiles;
1982	    delete spec.scanFiles;
1983	    if (scanClasses.length) throw new Error(`${where}: scanFileClasses cannot combine with a field-named scanFiles`);
1984	    if (!(spec.namedScan.inParsedFilesMatching instanceof RegExp) || typeof spec.namedScan.namedByField !== 'string') {
1985	      throw new Error(`${where}: a field-named scanFiles needs "inParsedFilesMatching" (the documents that name files) and "namedByField" (the field holding each name)`);
1986	    }
1987	    if (spec.namedScan.whereFileContains && !(spec.namedScan.whereFileContains instanceof RegExp)) {
1988	      throw new Error(`${where}: "whereFileContains" refines the naming documents by their text, so it takes a regex`);
1989	    }
1990	  }
1991	  // The normalized selection surface the scan reads: the sweep patterns
1992	  // (regex scanFiles + classes) and every exclusion (declared, class-named,
1993	  // and the loader-supplied self-exclusion) as flat lists.
1994	  spec.scanMatchers = [...(spec.scanFiles instanceof RegExp ? [spec.scanFiles] : []), ...scanClasses];
1995	  spec.excludeMatchers = [
1996	    ...(spec.excludeFiles != null ? [spec.excludeFiles] : []),
1997	    ...classPatterns(spec.excludeFileClasses),
1998	    ...(selfExclude ? [selfExclude] : []),
1999	  ];
2000	  if (typeof spec.fix === 'string') applyFixDefault(spec, spec.fix);
2001	  if (spec.forbidReferences !== undefined) {
2002	    const { edges, errors } = normalizeEdges(spec.forbidReferences);
2003	    if (errors.length) throw new Error(`${where}: ${errors[0].what} — ${errors[0].fix}`);
2004	    spec.edges = edges;
2005	  }
2006	  const rule = {
2007	    id: spec.id,
2008	    severity: spec.severity,
2009	    ...(spec.since ? { since: spec.since } : {}),
2010	    why: spec.failureMessage,
2011	    ...(spec.scope ? { scope: spec.scope } : {}),
2012	    spec,
2013	    // A work-scoped rule is handed the fluent work surface (runRule dispatches
2014	    // on the scope above); the scan machinery underneath it still reads the raw
2015	    // context the surface wraps.
2016	    run(input) {
2017	      if (spec.scope === 'action') return actionFindings(rule, input);
2018	      const work = spec.scope === 'work' ? input : null;
2019	      if (work && spec.whenReplyClassIncludes !== undefined && !replyGateOpen(work, spec.whenReplyClassIncludes)) return [];
2020	      const scanned = results(work ? work.ctx : input).get(rule);
2021	      return work ? [...scanned, ...workFindings(rule, work)] : scanned;
2022	    },
2023	  };
2024	  REGISTRY.push(rule);
2025	  return rule;
2026	}
2027	
2028	// A directory's declared checks: `<dir>/declared-checks.json`, an array of specs
2029	// compiled into rules — none when the file is absent. Cached by path, so the
2030	// registry and a test asking the same directory share one set of rule objects
2031	// (two would each re-run the shared scan for the same assertions).
2032	//
2033	// A SKILL's declarations (a dir named `…/skills/<name>`) are compiled with a
2034	// structural self-exclusion — content under any `skills/<name>/` path segment
2035	// pair is out of every assertion's scope — so a skill's own SKILL.md examples
2036	// never trip its checks, in whichever tree the skill's content appears (the
2037	// canon's packs/<pack>/skills/, a root skills/ layout, a consumer's mounted
2038	// .claude/skills/ links), without each declaration hand-spelling the exclusion.
2039	const loaded = new Map();
2040	export function loadDeclaredChecks(dir) {
2041	  const path = join(dir, 'declared-checks.json');
2042	  if (!loaded.has(path)) {
2043	    let specs = [];
2044	    if (existsSync(path)) {
2045	      let raw;
2046	      try { raw = JSON.parse(readFileSync(path, 'utf8')); }
2047	      catch (e) { throw new Error(`${path} is not valid JSON: ${e.message}`); }
2048	      if (!Array.isArray(raw)) throw new Error(`${path} must be an array of check declarations`);
2049	      specs = raw;
2050	    }
2051	    const skillName = /(^|[\\/])skills[\\/]([^\\/]+)$/.exec(dir)?.[2];
2052	    const selfExclude = skillName ? new RegExp(`(^|/)skills/${escapeRe(skillName)}/`) : null;
2053	    loaded.set(path, specs.map((s) => patternRule(s, { selfExclude })));
2054	  }
2055	  return loaded.get(path);
2056	}

