  const rule = ruleById('custom-source-annotated-nothing-to-add');
  assert.deepEqual(rule.run(worldCtx({
    'extension/event-extractors/custom/thinkdrink.js': 'GCal.sources.push({ name: "thinkdrink" });\n',
  })), []);
