    "scanFiles": "/^extension\\/event-extractors\\/custom\\/[^/]+\\.js$/",
    "matchLines": [
      {
        "match": "/nothing to add/i",
        "what": "{path} is annotated \"nothing to add\" instead of being deleted",
        "fix": "delete this file — a site with nothing to override stays listed in supportedDomains with no custom/ file at all"
      }
    ]
  },
  {
    "id": "git-checkout-paths-and-branch-move-combined",
    "severity": "advisory",
    "since": "2026-09-13",
    "scope": "action",
    "failureMessage": "combining `git checkout <branch> -- <paths>` with `git checkout -b` in one command silently discards uncommitted edits on those paths — the #734 one-liner that wiped three finished edits",
    "guardToolCalls": [
      {
        "tool": "Bash",
        "inputField": "command",
        "match": "/(?=[\\s\\S]*git checkout \\S+ -- )(?=[\\s\\S]*git checkout -b )/",
        "what": "a single command combining a path-restoring `git checkout <branch> -- <paths>` with `git checkout -b`",
        "fix": "split them into two calls — commit or `git stash` any edits on those paths first, then run the restore and the branch move separately, never in the same `&&` chain"
      }
    ]
  }
]

